import React, { useState } from "react";
import "./../css/nav.css"; // استایل‌ها رو داخل این فایل می‌ریزیم

// اگه از FontAwesome به‌صورت package استفاده می‌کنی:
// import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
// import { faHouse, faMagnifyingGlass, faCompass, faPaperPlane, faUser } from "@fortawesome/free-solid-svg-icons";

const Navbar = () => {
    // لیست آیتم‌ها (برای راحتی)
    const navItems = [
        { id: "home", icon: "fa-house", label: "Home" },
        { id: "search", icon: "fa-magnifying-glass", label: "Search" },
        { id: "explore", icon: "fa-compass", label: "Explore" },
        { id: "message", icon: "fa-paper-plane", label: "Message" },
        { id: "profile", icon: "fa-user", label: "Profile" },
    ];

    // state برای آیتم فعال (پیش‌فرض profile)
    const [activeId, setActiveId] = useState("profile");

    // آیتم فعال رو پیدا می‌کنیم تا آیکون و لیبلش رو توی محتوای وسط نشون بدیم
    const activeItem = navItems.find((item) => item.id === activeId);

    const handleClick = (id) => {
        setActiveId(id);
    };

    return (
        <>
            <div className="page-content" id="pageContent">
                <div className="content-icon">
                    {/* اگه از FontAwesome package استفاده می‌کنی، به‌جای i از <FontAwesomeIcon> استفاده کن */}
                    <i className={`fa-duotone fa-solid ${activeItem?.icon}`}></i>
                </div>
                <div className="content-label">{activeItem?.label}</div>
            </div>

            {/* نوار ناوبری */}
            <div className="nav-outer">
                <nav className="dark-navbar" id="mainNavbar">
                    {navItems.map((item) => (
                        <div
                            key={item.id}
                            className={`nav-item ${activeId === item.id ? "active" : ""}`}
                            data-icon={item.icon}
                            data-label={item.label}
                            onClick={() => handleClick(item.id)}
                        >
                            <div className="icon-circle">
                                <i className={`fa-duotone fa-solid ${item.icon}`}></i>
                            </div>
                            <span>{item.label}</span>
                        </div>
                    ))}
                </nav>
            </div>
        </>
    );
};

export default Navbar;
